<script setup>
import { computed, inject, onMounted, reactive, ref, watch } from "vue"; import { RouterLink, useRoute, useRouter } from "vue-router"; import PageHeader from "../components/PageHeader.vue"; import EmptyState from "../components/EmptyState.vue"; import StatusBadge from "../components/StatusBadge.vue";
const props = defineProps({ elementId: String }); const services = inject("services"); const builtInRuleSets = inject("builtInRuleSets"); const route = useRoute(); const router = useRouter(); const element = ref(); const environment = ref(); const ruleSets = ref([]); const evaluation = ref(); const form = reactive({ name: "", ruleSet: "", data: {} }); const isNew = computed(() => !props.elementId); const checklist = computed(() => ruleSets.value.find(item => item.id === form.ruleSet));
async function load() { ruleSets.value = [...builtInRuleSets.map(entry => entry.ruleSet), ...await services.ruleSetService.list()]; if (!isNew.value) element.value = await services.repositories.elementRepository.get(props.elementId); const environmentId = element.value?.environmentId ?? route.query.environmentId; if (!environmentId || (!isNew.value && !element.value)) return; environment.value = await services.repositories.environmentRepository.get(environmentId); evaluation.value = element.value ? (await services.evaluationService.listEvaluations(element.value.id))[0] : undefined; form.name = element.value?.name ?? ""; form.ruleSet = route.query.ruleSet ?? element.value?.rule ?? ruleSets.value[0]?.id ?? ""; Object.assign(form.data, evaluation.value?.data ?? {}); }
watch(() => form.ruleSet, () => { const allowed = Object.keys(checklist.value?.parametros ?? {}); Object.keys(form.data).filter(key => !allowed.includes(key)).forEach(key => delete form.data[key]); });
async function save() { if (!checklist.value) return window.alert("Selecione um conjunto de regras."); const data = {}; for (const [key, parameter] of Object.entries(checklist.value.parametros ?? {})) { const value = form.data[key]; if (value !== "" && value !== undefined && value !== null) data[key] = parameter.tipo === "number" ? Number(value) : parameter.tipo === "boolean" ? value === true || value === "true" : value; } try { const saved = element.value ? await services.projectService.updateElement(element.value.id, { name: form.name, type: checklist.value.nome, rule: checklist.value.id }) : await services.projectService.createElement(environment.value.id, { name: form.name, type: checklist.value.nome, rule: checklist.value.id }); await services.evaluationService.evaluateElement({ elementId: saved.id, checklist: checklist.value, data }); router.push(`/elements/${saved.id}/evaluation`); } catch (error) { window.alert(error.message); } }
onMounted(load);
</script>
<template><template v-if="environment"><RouterLink class="back-link" :to="`/projects/${environment.projectId}/environments/${environment.id}`">‹ {{ environment.name }}</RouterLink><PageHeader :eyebrow="isNew ? 'Cadastro' : 'Elemento'" :title="isNew ? 'Novo elemento' : element.name" description="Escolha o tipo e informe as medidas observadas." /><form class="form-card" @submit.prevent="save"><label class="field"><span>Nome do elemento *</span><input v-model="form.name" required placeholder="Ex.: Porta principal"></label><label class="field"><span>Tipo de elemento *</span><select v-model="form.ruleSet"><option v-for="ruleSet in ruleSets" :key="ruleSet.id" :value="ruleSet.id">{{ ruleSet.nome }}</option></select></label><div class="form-divider"><strong>Dados para avaliação</strong><span>Campos definidos pelo conjunto de regras selecionado.</span></div><div class="fields-grid"><label v-for="(parameter, key) in checklist?.parametros" :key="key" class="field"><span>{{ parameter.label ?? key }}{{ parameter.obrigatorio ? ' *' : '' }} <small v-if="parameter.unidade">({{ parameter.unidade }})</small></span><select v-if="parameter.tipo === 'boolean'" v-model="form.data[key]" :required="parameter.obrigatorio"><option value="">Não informado</option><option :value="true">Sim</option><option :value="false">Não</option></select><select v-else-if="parameter.tipo === 'select'" v-model="form.data[key]" :required="parameter.obrigatorio"><option value="">Selecione</option><option v-for="option in parameter.opcoes ?? []" :key="option" :value="option">{{ option }}</option></select><input v-else v-model="form.data[key]" type="number" inputmode="decimal" step="any" :required="parameter.obrigatorio"></label></div><div class="form-actions"><RouterLink class="button button--ghost" :to="`/projects/${environment.projectId}/environments/${environment.id}`">Cancelar</RouterLink><button class="button">{{ isNew ? 'Salvar elemento' : 'Salvar alterações' }}</button><RouterLink v-if="!isNew" class="button button--outline" :to="`/elements/${element.id}/evaluation`"><StatusBadge :status="evaluation ? 'conforme' : 'nao_avaliado'" /> Ver resultado</RouterLink></div></form></template><EmptyState v-else title="Elemento não encontrado" text="Volte para o ambiente e tente novamente."><RouterLink class="button" to="/projects">Projetos</RouterLink></EmptyState></template>
